CREATE TYPE public.app_role AS ENUM ('owner');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'owner') $$;
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', icon text NOT NULL DEFAULT 'moon', sort_order int NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "visible categories" ON public.categories FOR SELECT TO anon,authenticated USING (visible OR public.is_owner()); CREATE POLICY "owner categories" ON public.categories FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.blog_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL DEFAULT '', slug text NOT NULL UNIQUE, excerpt text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', featured_image text, featured_image_alt text NOT NULL DEFAULT '', category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), published_at timestamptz, seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.blog_posts TO authenticated; GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "published posts" ON public.blog_posts FOR SELECT TO anon,authenticated USING ((status = 'published' AND published_at <= now()) OR public.is_owner()); CREATE POLICY "owner posts" ON public.blog_posts FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), image_url text NOT NULL, alt_text text NOT NULL DEFAULT '', caption text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.photos TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.photos TO authenticated; GRANT ALL ON public.photos TO service_role;
ALTER TABLE public.photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "visible photos" ON public.photos FOR SELECT TO anon,authenticated USING (visible OR public.is_owner()); CREATE POLICY "owner photos" ON public.photos FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.currently_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, value text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.currently_items TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.currently_items TO authenticated; GRANT ALL ON public.currently_items TO service_role;
ALTER TABLE public.currently_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "visible currently" ON public.currently_items FOR SELECT TO anon,authenticated USING (visible OR public.is_owner()); CREATE POLICY "owner currently" ON public.currently_items FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.homepage_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.homepage_notes TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.homepage_notes TO authenticated; GRANT ALL ON public.homepage_notes TO service_role;
ALTER TABLE public.homepage_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "visible notes" ON public.homepage_notes FOR SELECT TO anon,authenticated USING (visible OR public.is_owner()); CREATE POLICY "owner notes" ON public.homepage_notes FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.site_settings (id int PRIMARY KEY DEFAULT 1 CHECK (id = 1), tagline text NOT NULL DEFAULT '', intro text NOT NULL DEFAULT '', about_preview text NOT NULL DEFAULT '', about_body text NOT NULL DEFAULT '', about_image text, featured_post_id uuid REFERENCES public.blog_posts(id) ON DELETE SET NULL, social_links jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public settings" ON public.site_settings FOR SELECT TO anon,authenticated USING (true); CREATE POLICY "owner settings" ON public.site_settings FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), email text NOT NULL CHECK(length(email) BETWEEN 3 AND 320), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_messages TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "send message" ON public.contact_messages FOR INSERT TO anon,authenticated WITH CHECK (true); CREATE POLICY "owner messages" ON public.contact_messages FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner());
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TRIGGER touch_categories BEFORE UPDATE ON public.categories FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_blog_posts BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_photos BEFORE UPDATE ON public.photos FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_currently BEFORE UPDATE ON public.currently_items FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_notes BEFORE UPDATE ON public.homepage_notes FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_settings BEFORE UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER touch_messages BEFORE UPDATE ON public.contact_messages FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
